import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    n = int(input_data[0])
    k = int(input_data[1])

    max_pairs = k * (k - 1)
    if n > max_pairs:
        print("NO")
        return

    print("YES")

    pairs = []
    diff = 1
    start_b = 1

    while len(pairs) < n:
        for step in range(diff, k):
            if len(pairs) >= n:
                break
            b = start_b
            g = (start_b + step - 1) % k + 1
            if b != g:
                pairs.append((b, g))

        start_b += 1
        if start_b > k:
            start_b = 1
        diff += 1
        if diff > k:
            break

    for b, g in pairs:
        print(f"{b} {g}")

if __name__ == "__main__":
    solve()
